using System.Collections.ObjectModel; using System.Windows.Input; using KennelPro.Models.Dogs; using KennelPro.Models.Enums; using KennelPro.Models.Litters; using KennelPro.Models.Reproduction; using KennelPro.Services.Dogs; using KennelPro.Services.Reproduction;
namespace KennelPro.ViewModels.Reproduction;
public class ReproductionCrudViewModel:BaseViewModel,IQueryAttributable { readonly DogService _dogs; readonly HeatCycleService _cycles; readonly MatingService _matings; readonly LitterService _litters; readonly PuppyService _puppies; string _section="litter"; Guid? _parentId,_editId; public ObservableCollection<object> Items{get;}=new(); public ObservableCollection<Dog> Dogs{get;}=new(); public ICommand AddCommand{get;} public ICommand EditCommand{get;} public ICommand DeleteCommand{get;} public ICommand SaveCommand{get;} public ICommand OpenPuppiesCommand{get;} public ICommand BackCommand{get;} public string Title=>_section switch{"heat"=>"Heat Cycles","mating"=>"Matings","puppy"=>"Puppies",_=>"Litters"}; public bool IsHeat=>_section=="heat"; public bool IsMating=>_section=="mating"; public bool IsLitter=>_section=="litter"; public bool IsPuppy=>_section=="puppy"; public bool IsEditing{get=>_editing;set=>SetProperty(ref _editing,value);} bool _editing; public string Name{get=>_name;set=>SetProperty(ref _name,value);} string _name=""; public string Notes{get=>_notes;set=>SetProperty(ref _notes,value);} string _notes=""; public DateTime Date{get=>_date;set=>SetProperty(ref _date,value);} DateTime _date=DateTime.Today; public DateTime? EndDate{get=>_end;set=>SetProperty(ref _end,value);} DateTime? _end; public int Number{get=>_number;set=>SetProperty(ref _number,value);} int _number=1; public Gender Gender{get=>_gender;set=>SetProperty(ref _gender,value);} Gender _gender; public Dog? Mother{get=>_mother;set=>SetProperty(ref _mother,value);} Dog? _mother; public Dog? Father{get=>_father;set=>SetProperty(ref _father,value);} Dog? _father; public ReproductionCrudViewModel(DogService d,HeatCycleService c,MatingService m,LitterService l,PuppyService p){_dogs=d;_cycles=c;_matings=m;_litters=l;_puppies=p;AddCommand=new Command(()=>{_editId=null;Name="";Notes="";Date=DateTime.Today;EndDate=null;Number=1;IsEditing=true;});EditCommand=new Command<object>(async x=>await Edit(x));DeleteCommand=new Command<object>(async x=>await Delete(x));SaveCommand=new Command(async()=>await Save());OpenPuppiesCommand=new Command<object>(async x=>{if(x is Litter l)await Shell.Current.GoToAsync($"{nameof(Pages.Reproduction.ReproductionCrudPage)}?section=puppy&parentId={l.Id}");});BackCommand=new Command(async()=>await Shell.Current.GoToAsync(".."));} public void ApplyQueryAttributes(IDictionary<string,object> q){if(q.TryGetValue("section",out var s))_section=s?.ToString()??"litter";if(q.TryGetValue("parentId",out var p)&&Guid.TryParse(p?.ToString(),out var id))_parentId=id;OnPropertyChanged(nameof(Title));OnPropertyChanged(nameof(IsHeat));OnPropertyChanged(nameof(IsMating));OnPropertyChanged(nameof(IsLitter));OnPropertyChanged(nameof(IsPuppy));} public async Task LoadAsync(){Dogs.Clear();foreach(var d in await _dogs.GetDogsForCurrentKennelAsync())Dogs.Add(d);Items.Clear();IEnumerable<object> x=IsHeat&&_parentId.HasValue?(await _cycles.GetForDogAsync(_parentId.Value)).Cast<object>():IsMating?(await _matings.GetForCurrentKennelAsync()).Cast<object>():IsPuppy&&_parentId.HasValue?(await _puppies.GetForLitterAsync(_parentId.Value)).Cast<object>(): (await _litters.GetForCurrentKennelAsync()).Cast<object>();foreach(var i in x)Items.Add(i);} async Task Edit(object? x){if(x==null)return;_editId=x switch{HeatCycle a=>a.Id,Mating a=>a.Id,Litter a=>a.Id,Puppy a=>a.Id,_=>null};if(_editId==null)return;switch(x){case HeatCycle a:Date=a.StartDate;EndDate=a.EndDate;Notes=a.Notes??"";break;case Mating a:Date=a.Date;Notes=a.Notes??"";Mother=Dogs.FirstOrDefault(d=>d.Id==a.FemaleDogId);Father=Dogs.FirstOrDefault(d=>d.Id==a.MaleDogId);break;case Litter a:Name=a.Name;Date=a.BirthDate;Notes=a.Notes??"";Mother=Dogs.FirstOrDefault(d=>d.Id==a.MotherDogId);Father=Dogs.FirstOrDefault(d=>d.Id==a.FatherDogId);break;case Puppy a:Name=a.Name;Number=a.Number;Date=a.BirthDate;Notes=a.Notes??"";Gender=a.Gender;break;}IsEditing=true;} async Task Save(){(bool ok,string e) r; if(IsHeat)r=_editId==null?await _cycles.AddAsync(new(){DogId=_parentId??Guid.Empty,StartDate=Date,EndDate=EndDate,Notes=Notes}):await _cycles.UpdateAsync(new(){Id=_editId.Value,StartDate=Date,EndDate=EndDate,Notes=Notes});else if(IsMating)r=_editId==null?await _matings.AddAsync(new(){FemaleDogId=Mother?.Id??Guid.Empty,MaleDogId=Father?.Id??Guid.Empty,Date=Date,Notes=Notes}):await _matings.UpdateAsync(new(){Id=_editId.Value,FemaleDogId=Mother?.Id??Guid.Empty,MaleDogId=Father?.Id??Guid.Empty,Date=Date,Notes=Notes});else if(IsLitter)r=_editId==null?await _litters.AddAsync(new(){Name=Name,BirthDate=Date,Notes=Notes,MotherDogId=Mother?.Id??Guid.Empty,FatherDogId=Father?.Id??Guid.Empty}):await _litters.UpdateAsync(new(){Id=_editId.Value,Name=Name,BirthDate=Date,Notes=Notes,MotherDogId=Mother?.Id??Guid.Empty,FatherDogId=Father?.Id??Guid.Empty});else r=_editId==null?await _puppies.AddAsync(new(){LitterId=_parentId??Guid.Empty,Name=Name,Number=Number,Gender=Gender,BirthDate=Date,Notes=Notes}):await _puppies.UpdateAsync(new(){Id=_editId.Value,Name=Name,Number=Number,Gender=Gender,BirthDate=Date,Notes=Notes});if(!r.ok){await Shell.Current.DisplayAlertAsync("Error",r.e,"OK");return;}IsEditing=false;await LoadAsync();} async Task Delete(object? x){if(x==null||!await Shell.Current.DisplayAlertAsync("Delete","Delete this entry?","Delete","Cancel"))return;bool ok=x switch{HeatCycle a=>await _cycles.DeleteAsync(a.Id),Mating a=>await _matings.DeleteAsync(a.Id),Litter a=>await _litters.DeleteAsync(a.Id),Puppy a=>await _puppies.DeleteAsync(a.Id),_=>false};if(ok)await LoadAsync();} }
